def count_islands(grid) -> int:
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    visited = [[False] * cols for _ in range(rows)]
    count = 0

    def bfs(sr, sc):
        stack = [(sr, sc)]
        visited[sr][sc] = True
        while stack:
            r, c = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] == '#':
                        visited[nr][nc] = True
                        stack.append((nr, nc))

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '#' and not visited[i][j]:
                count += 1
                bfs(i, j)

    return count
